                    print('  span',s['font'],round(s['size'],2),[round(v,2) for v in s['bbox']])
    # drawings
    for dr in p.get_drawings():
        r=dr['rect']
        if dr.get('dashes') and dr['dashes']!='[] 0':
            print('DASH',dr['dashes'],[round(v,2) for v in r],dr.get('color'),dr.get('width'))
